    max_sum = 2 * k * (k + 1) // 2

    if n < min_sum or n > max_sum:
        print("NO")
        return

    print("YES")
    a = [0] * k
    remaining = n

    for i in range(k - 1, -1, -1):
        if remaining > 2 * i:
            a[i] = 2 * i
            remaining -= 2 * i
        else:
            a[i] = remaining
            remaining = 0

    for i in range(k - 2, -1, -1):
        if a[i] < a[i + 1]:
            a[i] = a[i + 1] - 1

    print(*a)

