def solve_problem_competition(n, k):
    if k > n:
        print("NO")
        return

    a = [1] * k
    remaining = n - k

    for i in range(k - 1, -1, -1):
        if remaining == 0:
            break
        if remaining > 0:
            add = min(remaining, 2 * a[i] - a[i])
            a[i] += add
            remaining -= add
        else:
            if a[i] > 1:
                a[i] -= 1
                remaining += 1

    if remaining > 0:
        print("NO")
    else:
        print("YES")
        print(*a)

